using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;

    vector<long long> a(n + 1);
    vector<int> balance(n + 1, 0);

    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        balance[i] = balance[i - 1] + (a[i] % 2 == 0 ? 1 : -1);
    }

    if (balance[n] != 0) {
        cout << 0;
        return 0;
    }

    vector<long long> costs;
    for (int i = 1; i < n; ++i) {
        if (balance[i] == 0)
            costs.push_back(llabs(a[i + 1] - a[i]));
    }

    sort(costs.begin(), costs.end());

    int answer = 0;
    for (long long cost : costs) {
        if (cost > m) break;
        m -= cost;
        ++answer;
    }

    cout << answer;
    return 0;
